import{_ as a,o as r,c as i,j as t,a as s,a5 as o}from"./chunks/framework.BF53ZjCA.js";const y=JSON.parse(`{"title":"Find a Gemstone's Coordinates","description":"Build a first map of gemstone classification through materials, structure, optical phenomena, and color causes.","frontmatter":{"title":"Find a Gemstone's Coordinates","description":"Build a first map of gemstone classification through materials, structure, optical phenomena, and color causes."},"headers":[],"relativePath":"classification/intro.md","filePath":"classification/intro.md","lastUpdated":1790876393000}`),n={name:"classification/intro.md"};function l(d,e,h,c,m,u){return r(),i("div",null,[...e[0]||(e[0]=[t("h1",{id:"find-a-gemstone-s-coordinates",tabindex:"-1"},[s("Find a Gemstone's Coordinates "),t("a",{class:"header-anchor",href:"#find-a-gemstone-s-coordinates","aria-label":`Permalink to "Find a Gemstone's Coordinates"`},"​")],-1),t("blockquote",null,[t("p",null,"From materials and structure to optical phenomena, a first map of the gemstone world.")],-1),t("p",null,"Classification is not a label placed on a stone. It answers four questions: what it is, how it formed, how it presents light, and where to look next.",-1),t("div",{class:"classification-map",role:"list","aria-label":"Four ways to observe a gemstone"},[t("a",{class:"classification-map__item",href:"./mineral-groups/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"01"),t("strong",null,"Material"),t("span",null,"What it is")]),t("a",{class:"classification-map__item",href:"./crystal-systems/cubic",role:"listitem"},[t("span",{class:"classification-map__index"},"02"),t("strong",null,"Structure"),t("span",null,"How it is arranged")]),t("a",{class:"classification-map__item",href:"./optical-phenomena/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"03"),t("strong",null,"Optics"),t("span",null,"How it shows light")]),t("a",{class:"classification-map__item",href:"./color-causes/intro",role:"listitem"},[t("span",{class:"classification-map__index"},"04"),t("strong",null,"Color"),t("span",null,"Why it is colored")])],-1),o('<blockquote><p>These four entries are intersecting coordinates, not mutually exclusive categories. A single gem can have material, structural, optical, and color information at the same time.</p></blockquote><h2 id="_01-·-what-is-it-material-origin-and-identity" tabindex="-1">01 · What is it? Material, origin, and identity <a class="header-anchor" href="#_01-·-what-is-it-material-origin-and-identity" aria-label="Permalink to &quot;01 · What is it? Material, origin, and identity&quot;">​</a></h2><p>Many natural gemstones are minerals, but gem materials are not limited to minerals. Start by asking what the material is, then ask where it came from and whether it was treated, and finally clarify how its name relates to other gem names. This keeps material identity, provenance, and imitation from being mixed into one axis.</p><h3 id="a-first-identify-the-material" tabindex="-1">A. First identify the material <a class="header-anchor" href="#a-first-identify-the-material" aria-label="Permalink to &quot;A. First identify the material&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Material layer</th><th>What to ask</th><th>Representative materials</th></tr></thead><tbody><tr><td>Natural minerals</td><td>Can its composition and crystal structure be used to define it?</td><td>Corundum, beryl, quartz, diamond</td></tr><tr><td>Amorphous / mineraloid materials</td><td>Does it lack a typical long-range crystal order?</td><td>Opal, natural glass such as obsidian</td></tr><tr><td>Organic materials</td><td>Was it formed through biological activity or biogenic processes?</td><td>Pearl, amber, coral</td></tr></tbody></table><h3 id="b-then-identify-origin-and-relationship" tabindex="-1">B. Then identify origin and relationship <a class="header-anchor" href="#b-then-identify-origin-and-relationship" aria-label="Permalink to &quot;B. Then identify origin and relationship&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Identity dimension</th><th>What to ask</th><th>Examples</th></tr></thead><tbody><tr><td>Natural</td><td>Was it formed in nature rather than made in a laboratory?</td><td>Natural ruby, natural opal</td></tr><tr><td>Synthetic</td><td>Was it made in a laboratory with chemistry and structure comparable to a natural counterpart?</td><td>Synthetic ruby, synthetic emerald, CVD diamond</td></tr><tr><td>Treated</td><td>Was a natural or synthetic material altered to change appearance or durability?</td><td>Heating, filling, dyeing; disclose separately</td></tr><tr><td>Composite / assembled</td><td>Was the finished object built from two or more materials?</td><td>Doublets, triplets</td></tr><tr><td>Simulant</td><td>Is another material being used to imitate a target gem? It is not one fixed material.</td><td>Cubic zirconia, glass, moissanite when used as a diamond simulant</td></tr></tbody></table><blockquote><p>A learner&#39;s rule: <strong>What is the material? Where did it come from? Was it treated? Is it imitating another gem?</strong> Answer these separately.</p></blockquote><h3 id="c-finally-identify-the-naming-level" tabindex="-1">C. Finally identify the naming level <a class="header-anchor" href="#c-finally-identify-the-naming-level" aria-label="Permalink to &quot;C. Finally identify the naming level&quot;">​</a></h3><p>GIA uses three useful levels here: a <strong>mineral group</strong> contains related mineral species; a <strong>mineral species</strong> is defined by chemistry and crystal structure; a <strong>gem variety</strong> is commonly distinguished by color or other visible features.</p><table tabindex="0"><thead><tr><th>Level example</th><th>Relationship</th><th>Introductory example</th></tr></thead><tbody><tr><td>Mineral species → gem varieties</td><td>One species can correspond to several gem varieties</td><td>Corundum → ruby, sapphire</td></tr><tr><td>Mineral species → gem varieties</td><td>Color and appearance create familiar gem names</td><td>Beryl → emerald, aquamarine, morganite</td></tr><tr><td>Mineral group → multiple species</td><td>One group can contain several related species</td><td>Garnet group → multiple garnet species and varieties</td></tr><tr><td>Mineral species → commercial appearance terms</td><td>A species can also be described by color or market language</td><td>Diamond → colourless diamond, fancy-colour diamond</td></tr></tbody></table><blockquote><p>“Precious” and “semi-precious” are traditional commercial terms, not strict modern gemological categories. Value is better discussed through rarity, beauty, durability, treatment, and market demand.</p></blockquote><p><strong>Sources:</strong> <a href="https://elearning-samples.gia.edu/Gem_Identification/Page5.html" target="_blank" rel="noreferrer">GIA: Gem Species, Varieties, and Groups</a> · <a href="https://www.gia.edu/gem-synthetic" target="_blank" rel="noreferrer">GIA: Synthetic Gem Materials</a> · <a href="https://www.gia.edu/gem-imitation" target="_blank" rel="noreferrer">GIA: Imitation Diamonds and Other Gems</a> · <a href="https://www.gia.edu/FAQ/gia-faq-about-gemstones-difference-treatment-enhancement" target="_blank" rel="noreferrer">GIA: Treatment and Enhancement FAQ</a></p><h2 id="_02-·-how-is-it-arranged-crystal-systems-and-structure" tabindex="-1">02 · How is it arranged? Crystal systems and structure <a class="header-anchor" href="#_02-·-how-is-it-arranged-crystal-systems-and-structure" aria-label="Permalink to &quot;02 · How is it arranged? Crystal systems and structure&quot;">​</a></h2><p>Crystal structure describes the ordered arrangement of atoms or ions in space. The seven crystal systems describe symmetry and axial relationships. They are structural coordinates that help explain optical behavior, cleavage, crystal habit, and some identification clues—not simple names for the visible outline of a finished gem.</p><h3 id="seven-crystal-systems-describing-symmetry" tabindex="-1">Seven crystal systems: describing symmetry <a class="header-anchor" href="#seven-crystal-systems-describing-symmetry" aria-label="Permalink to &quot;Seven crystal systems: describing symmetry&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Crystal system</th><th>Structural feature</th><th>Representative gems</th><th>Learning cue</th></tr></thead><tbody><tr><td><a href="./crystal-systems/cubic.html">Cubic / isometric</a></td><td>Three equal, mutually perpendicular axes</td><td>Diamond, spinel, garnet</td><td>Highest symmetry among the seven systems</td></tr><tr><td><a href="./crystal-systems/tetragonal.html">Tetragonal</a></td><td>Two equal, perpendicular axes and a distinct third axis</td><td>Zircon, rutile</td><td>Compare the equal axes with the principal axis</td></tr><tr><td><a href="./crystal-systems/orthorhombic.html">Orthorhombic</a></td><td>Three unequal, mutually perpendicular axes</td><td>Tanzanite, chrysoberyl, topaz</td><td>All three right-angle relationships remain</td></tr><tr><td><a href="./crystal-systems/hexagonal.html">Hexagonal</a></td><td>A sixfold principal symmetry axis</td><td>Beryl, apatite</td><td>Distinguish its principal symmetry from trigonal</td></tr><tr><td><a href="./crystal-systems/trigonal.html">Trigonal</a></td><td>A threefold principal symmetry axis</td><td>Ruby, sapphire, quartz, tourmaline</td><td>Corundum, quartz, and tourmaline are important gem groups</td></tr><tr><td><a href="./crystal-systems/monoclinic.html">Monoclinic</a></td><td>Three unequal axes; only two angle pairs are right angles</td><td>Orthoclase, spodumene</td><td>Structural anisotropy affects optics and cleavage</td></tr><tr><td><a href="./crystal-systems/triclinic.html">Triclinic</a></td><td>Three unequal axes with no right-angle requirement</td><td>Kyanite, turquoise</td><td>Lowest symmetry among the seven systems</td></tr></tbody></table><p><span id="amorphous-materials"></span></p><h3 id="amorphous-materials-outside-the-crystal-systems" tabindex="-1">Amorphous materials: outside the crystal systems <a class="header-anchor" href="#amorphous-materials-outside-the-crystal-systems" aria-label="Permalink to &quot;Amorphous materials: outside the crystal systems&quot;">​</a></h3><p>Opal, natural glass such as obsidian, and amber should not be presented as an “eighth crystal system.” They need to be described separately by material structure: without complete long-range crystal order, they cannot be assigned the axial relationships used by the seven systems.</p><table tabindex="0"><thead><tr><th>Material state</th><th>Representative material</th><th>Learning focus</th></tr></thead><tbody><tr><td>Amorphous / mineraloid</td><td>Opal</td><td>Study hydrated silica structure and play of color rather than looking for a crystal system</td></tr><tr><td>Natural glass</td><td>Obsidian</td><td>Study glassy structure and formation rather than crystal symmetry</td></tr><tr><td>Organic material</td><td>Amber</td><td>Start with biogenic origin, then distinguish it from mineral crystal classification</td></tr></tbody></table><blockquote><p>For a finished cut gem, the outline alone is not enough to determine its crystal system. Use mineralogical references together with optical behavior, refractive index, birefringence, and structural evidence.</p></blockquote><h3 id="three-terms-learners-often-confuse" tabindex="-1">Three terms learners often confuse <a class="header-anchor" href="#three-terms-learners-often-confuse" aria-label="Permalink to &quot;Three terms learners often confuse&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Term</th><th>What it describes</th><th>Do not confuse it with</th></tr></thead><tbody><tr><td>Crystal system</td><td>Internal symmetry and axial relationships</td><td>What shape a finished gem appears to have</td></tr><tr><td>Crystal form / habit</td><td>The external form produced as a crystal grows</td><td>The outline created by a cutter</td></tr><tr><td>Cut</td><td>Human-designed facets, proportions, and polish</td><td>Which crystal system the material belongs to</td></tr></tbody></table><p><em>Begin with the <a href="./crystal-systems/cubic.html">cubic system</a>, then compare how symmetry relates to gem properties.</em></p><p><strong>Sources:</strong> <a href="https://www.open.edu/openlearn/science-maths-technology/an-introduction-minerals-and-rocks-under-the-microscope/content-section-1.6.3/?tip=linktip" target="_blank" rel="noreferrer">Open University: Crystal systems</a> · <a href="https://australian.museum/learn/minerals/what-are-minerals/crystallography/" target="_blank" rel="noreferrer">Australian Museum: Crystallography</a> · <a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA: Structures Behind the Spectacle</a></p><h2 id="_03-·-how-does-it-show-light-optical-phenomena" tabindex="-1">03 · How does it show light? Optical phenomena <a class="header-anchor" href="#_03-·-how-does-it-show-light-optical-phenomena" aria-label="Permalink to &quot;03 · How does it show light? Optical phenomena&quot;">​</a></h2><p>Optical phenomena are an important observational entry point, but a visible effect, its cause, and its trade name should not be treated as the same thing. GemAtlas records what is seen, how to observe it, and which structures or inclusions may produce it.</p><table tabindex="0"><thead><tr><th>Phenomenon</th><th>Visible expression</th><th>How to observe</th><th>Representative materials</th></tr></thead><tbody><tr><td>Asterism</td><td>Intersecting rays form a star</td><td>Use a single point light and slowly rotate the cabochon</td><td>Star ruby, star sapphire</td></tr><tr><td>Chatoyancy</td><td>A movable band of light appears</td><td>Move the light or rotate the cabochon to see whether the band moves</td><td>Cat&#39;s-eye chrysoberyl, tiger&#39;s eye</td></tr><tr><td>Color change</td><td>Color shifts under different light sources</td><td>Compare daylight with incandescent or warm light</td><td>Alexandrite, color-change sapphire</td></tr><tr><td>Play of color</td><td>Angle-dependent spectral flashes shift across the surface</td><td>Slowly tilt the gem and watch the patches move and reorganize</td><td>Opal</td></tr><tr><td>Iridescence</td><td>Thin or layered structures produce interference colors</td><td>Change the viewing angle and follow broad color bands</td><td>Labradorite and related materials</td></tr><tr><td>Adularescence</td><td>A soft blue-white floating glow</td><td>Rotate the cabochon and follow the drifting sheen</td><td>Moonstone</td></tr><tr><td>Aventurescence</td><td>Plate-like inclusions create sparkle</td><td>Tilt the gem so individual platelets catch the light</td><td>Aventurine, sunstone</td></tr></tbody></table><blockquote><p>Seeing a phenomenon only establishes an optical appearance; it is not a final identification. Lighting, cut, viewing angle, and inclusions all affect what the observer sees.</p></blockquote><h2 id="three-observation-rules" tabindex="-1">Three observation rules <a class="header-anchor" href="#three-observation-rules" aria-label="Permalink to &quot;Three observation rules&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Rule</th><th>Why it matters</th><th>Typical use</th></tr></thead><tbody><tr><td>Change the light source</td><td>Some effects depend on the spectrum of the light, not only the viewing angle</td><td>Color change</td></tr><tr><td>Change the viewing angle</td><td>Directional reflection, interference, and diffraction can move or change the effect</td><td>Play of color, adularescence, iridescence</td></tr><tr><td>Use a controlled point light</td><td>A focused source makes directional reflections easier to see</td><td>Asterism, chatoyancy</td></tr></tbody></table><p>The detailed pages below connect each visible effect to its likely structural cause, typical examples, and identification limits. Treat the observation as evidence to record—not as a shortcut to a name.</p><p><em>Return to the <a href="./intro.html">classification overview</a>, or enter the detailed <a href="./intro.html">Optical Phenomena</a> pages for causes, examples, and identification notes.</em></p><p><strong>Sources:</strong> <a href="https://www.gia.edu/articles/gems-gemology-summary-guide-to-phenomenal-gems" target="_blank" rel="noreferrer">GIA: Guide to Phenomenal Gems</a> · <a href="https://www.gia.edu/gia-news-research/optical-effects-phenomenal-cabochons" target="_blank" rel="noreferrer">GIA: Optical Effects of Phenomenal Cabochons</a> · <a href="https://www.gia.edu/gems-gemology/summer-2025-phenomenal-gemstones" target="_blank" rel="noreferrer">GIA: Structures Behind the Spectacle</a></p><h2 id="_04-·-why-is-it-colored-causes-of-color" tabindex="-1">04 · Why is it colored? Causes of color <a class="header-anchor" href="#_04-·-why-is-it-colored-causes-of-color" aria-label="Permalink to &quot;04 · Why is it colored? Causes of color&quot;">​</a></h2><p>Color is not an isolated surface label. It is the result of light interacting with matter. First distinguish absorption-based body color from structure-based optical color: ruby&#39;s red is mainly produced by selective absorption, while opal&#39;s play of color comes from diffraction and interference within microstructure.</p><table tabindex="0"><thead><tr><th>Observation path</th><th>What happens to light</th><th>Typical result</th></tr></thead><tbody><tr><td>Absorption-based body color</td><td>The gem selectively absorbs parts of visible light; the remainder reaches the eye</td><td>Body color in ruby, emerald, and sapphire</td></tr><tr><td>Structure-based optical color</td><td>Microstructure scatters, interferes with, or diffracts light; the result changes with angle or source</td><td>Opal play of color, moonstone sheen, labradorite iridescence</td></tr></tbody></table><h3 id="three-common-absorption-mechanisms" tabindex="-1">Three common absorption mechanisms <a class="header-anchor" href="#three-common-absorption-mechanisms" aria-label="Permalink to &quot;Three common absorption mechanisms&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mechanism</th><th>Core question</th><th>Representative direction</th></tr></thead><tbody><tr><td>Transition-metal ions</td><td>Which wavelengths are selectively absorbed by ions in the lattice?</td><td>Chromium, iron, manganese, cobalt, copper</td></tr><tr><td>Color centers</td><td>How do lattice defects change light absorption?</td><td>Vacancies, interstitials, irradiation-related defects</td></tr><tr><td>Charge transfer</td><td>How do electrons move between neighboring ions or energy levels?</td><td>Metal–metal and oxygen–metal transfer</td></tr></tbody></table><p>Color grouping is useful for observation and search, but it cannot replace identification. The same visible color can arise from different mechanisms; a proper color description also considers hue, tone, saturation, lighting, and viewing direction.</p><p><em>See <a href="./color-causes/intro.html">Color Causes</a> to connect visible color with physical and chemical mechanisms.</em></p><h2 id="_05-·-from-coordinates-to-the-gemstone-index" tabindex="-1">05 · From coordinates to the Gemstone Index <a class="header-anchor" href="#_05-·-from-coordinates-to-the-gemstone-index" aria-label="Permalink to &quot;05 · From coordinates to the Gemstone Index&quot;">​</a></h2><p>A single gemstone can occupy several coordinates. Opal, for example, is an amorphous or mineraloid material and may display play of color. Sapphire is a gem variety within the mineral species corundum and has trigonal symmetry. Classification is not one box; it is a multidimensional index.</p><p>Every GemAtlas entry has its own page with physical properties, optical characteristics, treatments, and references. Continue through <a href="./mineral-groups/intro.html">Mineral Groups</a>, <a href="./crystal-systems/cubic.html">Crystal Systems</a>, or <a href="./optical-phenomena/intro.html">Optical Phenomena</a>. When you are ready to browse the complete collection, open the <a href="./../gems/">Gemstone Index</a>.</p><div class="classification-index-cta"><span class="classification-index-cta__count">60</span><div><strong>Gemstone Index · The Stone Index</strong><p>All 60 species in one searchable learning entry — from name and mineral family to the full reference page.</p></div><a href="../gems/">Browse the collection ↗</a></div>',46)])])}const g=a(n,[["render",l]]);export{y as __pageData,g as default};
